import{_ as r,o as a,c as d,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Эпоха Межплоскостных Исследований","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0078-跨位面探索纪元.md","filePath":"ru/0078-跨位面探索纪元.md"}'),l={name:"ru/0078-跨位面探索纪元.md"};function e(o,t,n,h,s,g){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="эпоха-межплоскостных-исследовании" tabindex="-1">Эпоха Межплоскостных Исследований <a class="header-anchor" href="#эпоха-межплоскостных-исследовании" aria-label="Permalink to &quot;Эпоха Межплоскостных Исследований&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>78</td></tr><tr><td>Модуль</td><td>Исторические эпохи и крупные события</td></tr><tr><td>Ключевые слова</td><td>Межплоскостные исследования, великие открытия плоскостей, археологический протокол, сначала наблюдение затем вмешательство, межзвёздный симбиоз</td></tr></tbody></table><h2 id="i-условия-открытия-эпохи-межплоскостных-исследовании" tabindex="-1">I. Условия открытия Эпохи Межплоскостных Исследований <a class="header-anchor" href="#i-условия-открытия-эпохи-межплоскостных-исследовании" aria-label="Permalink to &quot;I. Условия открытия Эпохи Межплоскостных Исследований&quot;">​</a></h2><p>Эпоха Межплоскостных Исследований — новая эпоха, открытая после основания Республики Десяти Тысяч Рас, соответствующая этапу перехода от «эволюции сознания» к «межзвёздному симбиозу» в пути четырёхэтапного повышения измерения. Открытие этой эпохи требовало одновременного созревания трёх условий:</p><ul><li><strong>Технологическое условие</strong>: технология пространственных правовых принципов достигла царства «Изначальной Пустоты», сделав возможным стабильное открытие межплоскостных каналов; Зеркало Репликации и технологии изолированного пространства созрели, обеспечив технические гарантии для исследований с низким загрязнением.</li><li><strong>Институциональное условие</strong>: основана Республика Десяти Тысяч Рас, завершены единые политики межплоскостных исследований и археологический протокол.</li><li><strong>Мотивационное условие</strong>: работа по повышению известных плоскостей продвигалась упорядоченно, и цивилизация имела как способность, так и желание расширяться к неизвестным плоскостям.</li></ul><p>Когда эти три условия созрели одновременно, Республика Десяти Тысяч Рас официально объявила о запуске «Большого Плана Исследований», и Эпоха Межплоскостных Исследований началась.</p><h2 id="ii-основные-принципы-межплоскостных-исследовании" tabindex="-1">II. Основные принципы межплоскостных исследований <a class="header-anchor" href="#ii-основные-принципы-межплоскостных-исследовании" aria-label="Permalink to &quot;II. Основные принципы межплоскостных исследований&quot;">​</a></h2><p>Межплоскостные исследования строго следуют следующим основным принципам, записанным в «Основном Законе Межплоскостных Исследований»:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Сначала наблюдение, затем ограниченное вмешательство</td><td>Неизвестные плоскости сначала подвергаются пассивному наблюдению; лишь после полного понимания осуществляются ограниченные контакты и вмешательство</td></tr><tr><td>Исследование с низким загрязнением</td><td>Применяет археологическую схему Зеркала Репликации + изолированного пространства, передавая обратно только знания, не внося и не вынося материю или жизнь</td></tr><tr><td>Защита аборигенных цивилизаций</td><td>Для плоскостей с аборигенными цивилизациями уважать их право на самостоятельное развитие; нельзя насильно насаждать симбиотическую систему</td></tr><tr><td>Совместное использование ресурсов</td><td>Знания и ресурсы, обнаруженные при исследовании, принадлежат всей цивилизации; никакая организация не может монополизировать результаты исследований</td></tr><tr><td>Безопасность прежде всего</td><td>Безопасность всегда ставится на первое место при исследованиях; исследование высокоопасных плоскостей должно проходить строгую оценку рисков</td></tr></tbody></table><h2 id="iii-технические-средства-исследования" tabindex="-1">III. Технические средства исследования <a class="header-anchor" href="#iii-технические-средства-исследования" aria-label="Permalink to &quot;III. Технические средства исследования&quot;">​</a></h2><p>Межплоскостные исследования комплексно применяли несколько центральных технологий симбиотической цивилизации:</p><ol><li><strong>Технология сканирования плоскостей</strong>: дистанционное сканирование плоскостей на основе модулей восприятия пространственных правовых принципов может получить базовую информацию о целевой плоскости без контакта с ней (пространственная структура, уровень энергии, признаки жизни и т. д.).</li><li><strong>Археологическая схема Зеркала Репликации</strong>: выполняет высокоточную зеркальную репликацию целевой плоскости, проводя углублённое исследование зеркальной копии в изолированном пространстве, передавая обратно только знания.</li><li><strong>Межплоскостные коммуникационные зонды</strong>: миниатюрные коммуникационные устройства законов, которые можно отправлять в целевую плоскость для наблюдения с близкого расстояния, данные передаются в реальном времени по межплоскостной коммуникационной сети.</li><li><strong>Восприятие домена сознания</strong>: высокоуровневые культиваторы дистанционно воспринимают целевую плоскость через домен сознания, получая информацию на уровне сознания, которую технология сканирования уловить не может.</li><li><strong>Удалённое развёртывание Якоря</strong>: для плоскостей с более высоким уровнем безопасности можно удалённо развернуть временные Якоря, установив стабильные каналы связи.</li></ol><h2 id="iv-организация-и-реализация-исследовании" tabindex="-1">IV. Организация и реализация исследований <a class="header-anchor" href="#iv-организация-и-реализация-исследовании" aria-label="Permalink to &quot;IV. Организация и реализация исследований&quot;">​</a></h2><p>Межплоскостные исследования организуются и реализуются единообразно «Бюро Межплоскостных Исследований» Республики Десяти Тысяч Рас, по модели «градуированных исследований»:</p><table tabindex="0"><thead><tr><th>Уровень исследования</th><th>Тип цели</th><th>Метод исследования</th><th>Комплектация персонала</th></tr></thead><tbody><tr><td>Исследования Первого Уровня</td><td>Безжизненные пустынные плоскости</td><td>Дистанционное сканирование + исследование Зеркалом Репликации</td><td>Преимущественно технические команды</td></tr><tr><td>Исследования Второго Уровня</td><td>Плоскости с низшей жизнью</td><td>Археология Зеркалом Репликации + ограниченное полевое изучение</td><td>Технические команды + биологи</td></tr><tr><td>Исследования Третьего Уровня</td><td>Плоскости с аборигенными цивилизациями</td><td>Сначала наблюдение, затем контакт, строгое соблюдение протокола контакта</td><td>Полная команда + дипломаты + этические наблюдатели</td></tr><tr><td>Исследования Четвёртого Уровня</td><td>Высокоопасные/неизвестные плоскости</td><td>Только моделирование в изолированном пространстве, полевой контакт запрещён</td><td>Команда безопасности высшего уровня</td></tr></tbody></table><p>Каждый исследовательский проект должен пройти полный процесс: «заявка на исследование — оценка рисков — этическая экспертиза — утверждение и реализация — мониторинг процесса — совместное использование результатов».</p><h2 id="v-великие-открытия-эпохи-исследовании" tabindex="-1">V. Великие открытия эпохи исследований <a class="header-anchor" href="#v-великие-открытия-эпохи-исследовании" aria-label="Permalink to &quot;V. Великие открытия эпохи исследований&quot;">​</a></h2><p>После открытия Эпохи Межплоскостных Исследований симбиотическая цивилизация совершила ряд великих открытий:</p><ul><li><strong>Открытие новых рас</strong>: в неизвестных плоскостях обнаружено большое количество ранее неизвестных разумных рас, генеалогия Десяти Тысяч Рас значительно расширена. Эти новые расы после добровольного выбора постепенно вступали в Республику Десяти Тысяч Рас.</li><li><strong>Открытие новых законов</strong>: структуры законов разных плоскостей различаются, при исследованиях обнаружено множество новых вариантов законов, обогативших теоретическую основу Трёхсот Систем Культивации.</li><li><strong>Руины древних цивилизаций</strong>: обнаружены руины нескольких вымерших цивилизаций Эпохи до Якоря, путём археологии Зеркалом Репликации получено большое количество ценных исторических знаний.</li><li><strong>Симбиотические цивилизации других плоскостей</strong>: на некоторых плоскостях обнаружены аборигенные цивилизации, независимо развившие концепцию симбиоза, образовавшие с Симбиотической Цивилизацией Якоря идейный резонанс через пространство.</li><li><strong>Исследование границы вселенной</strong>: исследования постепенно достигали известной границы Вселенной Хэнъюань, непрерывно углубляя понимание общей структуры вселенной.</li></ul><h2 id="vi-вызовы-и-размышления-в-исследованиях" tabindex="-1">VI. Вызовы и размышления в исследованиях <a class="header-anchor" href="#vi-вызовы-и-размышления-в-исследованиях" aria-label="Permalink to &quot;VI. Вызовы и размышления в исследованиях&quot;">​</a></h2><p>Межплоскостные исследования не были гладкими; процесс также столкнулся с вызовами:</p><ul><li><strong>Культурные конфликты</strong>: при контактах с аборигенными цивилизациями возникали культурные недопонимания и конфликты, что побуждало к постоянному совершенствованию протокола контакта.</li><li><strong>Этические споры об исследованиях</strong>: велись постоянные этические дебаты о том, «следует ли активно контактировать с аборигенными цивилизациями», в итоге сформирован консенсус «не инициативно, не избегая, уважая выбор».</li><li><strong>Инциденты безопасности</strong>: при исследовании высокоопасной плоскости произошёл прорыв барьера изолированного пространства; хотя серьёзных последствий не было, это способствовало дальнейшему повышению стандартов безопасности.</li><li><strong>Распределение ресурсов</strong>: масштабные исследования потребляют значительные ресурсы, и баланс между вложениями в исследования и вложениями в местную жизнеобеспеченность стал центром политических дебатов.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Эпоха Межплоскостных Исследований — «эпоха великих географических открытий» Симбиотической Цивилизации Якоря. Она расширила горизонты цивилизации от известных плоскостей до всей вселенной, углубив понимание себя в процессе открытия новых миров. Схема исследований с низким загрязнением — Зеркало Репликации + изолированное пространство — делает исследования симбиотической цивилизации принципиально отличными от любого хищнического колониального расширения в истории: мы несём не завоевание и хищничество, а уважение и знания; мы приносим обратно не ресурсы и рабов, а понимание и мудрость. Когда будет исследовано достаточно плоскостей и сеть Якоря станет достаточно плотной, дверь Эпохи Межзвёздного Симбиоза медленно откроется.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>77-万族共和成立 (Основание Республики Десяти Тысяч Рас)</li><li>79-星际共生时代展望 (Перспективы Эпохи Межзвёздного Симбиоза)</li><li>84-考古协议总纲 (Общие Основы Археологического Протокола)</li></ul>',26)])])}const c=r(l,[["render",e]]);export{b as __pageData,c as default};
